/** Modelul după slug-ul nou sau după cel vechi (link-uri vechi, coșuri, pilotul Trendyol). */
export function findCanvasProduct(slug: string): CanvasProduct | undefined {
  return canvasProducts.find((p) => p.slug === slug) ?? canvasProducts.find((p) => p.legacySlug === slug);
}
